/**
 * Throwaway probe: does the histogram brush work with real mouse input?
 * Not part of the repo (lives in /tmp); the durable checks go into
 * scripts/browser-check.mjs.
 */
import { spawn } from 'node:child_process';
import os from 'node:os';
import path from 'node:path';

const BASE = process.argv[2] ?? 'http://127.0.0.1:8787';
const PORT = 9333;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const userDataDir = path.join(os.tmpdir(), `brush-probe-${process.pid}`);
const chrome = spawn('chromium', [
  '--headless=new',
  `--remote-debugging-port=${PORT}`,
  `--user-data-dir=${userDataDir}`,
  '--no-first-run',
  '--no-default-browser-check',
  '--no-sandbox',
  '--disable-gpu',
  '--window-size=1440,1000',
  'about:blank',
], { stdio: ['ignore', 'ignore', 'pipe'] });

class CDP {
  constructor(ws) {
    this.ws = ws; this.id = 0; this.pending = new Map(); this.handlers = new Map();
    ws.addEventListener('message', (event) => {
      const message = JSON.parse(event.data);
      if (message.id && this.pending.has(message.id)) {
        const { resolve, reject } = this.pending.get(message.id);
        this.pending.delete(message.id);
        if (message.error) reject(new Error(message.error.message));
        else resolve(message.result);
        return;
      }
      for (const handler of this.handlers.get(message.method) ?? []) handler(message.params);
    });
  }
  send(method, params = {}) {
    const id = ++this.id;
    return new Promise((resolve, reject) => {
      this.pending.set(id, { resolve, reject });
      this.ws.send(JSON.stringify({ id, method, params }));
      setTimeout(() => { if (this.pending.delete(id)) reject(new Error(`${method} timed out`)); }, 30_000);
    });
  }
  on(method, fn) { this.handlers.set(method, [...(this.handlers.get(method) ?? []), fn]); }
  async eval(expression) {
    const { result, exceptionDetails } = await this.send('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
    if (exceptionDetails) throw new Error(exceptionDetails.exception?.description ?? 'eval failed');
    return result.value;
  }
  async waitFor(expression, { label = expression, timeout = 20_000 } = {}) {
    const start = Date.now();
    for (;;) {
      if (await this.eval(`Boolean(${expression})`)) return true;
      if (Date.now() - start > timeout) throw new Error(`timeout waiting for ${label}`);
      await sleep(150);
    }
  }
}

let version = null;
for (let i = 0; i < 60; i += 1) {
  try {
    version = await (await fetch(`http://127.0.0.1:${PORT}/json/version`)).json();
    break;
  } catch { await sleep(250); }
}
if (!version) { chrome.kill('SIGKILL'); throw new Error('chrome did not start'); }
const targets = await (await fetch(`http://127.0.0.1:${PORT}/json/list`)).json();
const target = targets.find((t) => t.type === 'page');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve) => ws.addEventListener('open', resolve, { once: true }));
const cdp = new CDP(ws);
await cdp.send('Page.enable');
await cdp.send('Runtime.enable');
await cdp.send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 1000, deviceScaleFactor: 1, mobile: false });

const out = [];
const log = (...a) => { out.push(a.join(' ')); console.log(...a); };

await cdp.send('Page.navigate', { url: `${BASE}/` });
await cdp.waitFor(`document.querySelectorAll('#result-list > *').length > 0`, { label: 'results' });
await sleep(600);

const geometry = await cdp.eval(`(() => {
  const host = document.querySelector('#year-histogram');
  const r = host.getBoundingClientRect();
  const bins = [...host.querySelectorAll('button')].map((b) => { const br = b.getBoundingClientRect(); return { start: Number(b.dataset.start), count: Number(b.dataset.count), x: br.x + br.width / 2, y: br.y + br.height - 8, h: b.getBoundingClientRect().height }; });
  const i = bins.findIndex((b) => b.count > 3);
  return { host: { x: r.x, y: r.y, w: r.width, h: r.height }, bins: binTrim(), first: i, top: host.scrollIntoView ? 0 : 0 };
  function binTrim() { return [...document.querySelectorAll('#year-histogram button')].map((b) => ({ start: Number(b.dataset.start), count: Number(b.dataset.count) })); }
})()`);
log('bins before:', JSON.stringify(geometry.bins.filter((b) => b.count > 0)));

// Which index has the most records?
const idx = geometry.bins.reduce((best, b, i) => (b.count > geometry.bins[best].count ? i : best), 0);
const binAt = (i) => geometry.bins[i];
log('busiest bin index:', idx, JSON.stringify(binAt(idx)));

const y = await cdp.eval(`(() => { const b = document.querySelectorAll('#year-histogram button')[${idx}]; const r = b.getBoundingClientRect(); return { x: r.x + r.width / 2, y: r.y + r.height - 6 }; })()`);

// --- drag across three bins (idx-2 .. idx) ---
const from = binAt(Math.max(0, idx - 2));
const to = binAt(idx);
const dragStart = await cdp.eval(`(() => { const b = document.querySelectorAll('#year-histogram button')[${Math.max(0, idx - 2)}]; const r = b.getBoundingClientRect(); return { x: r.x + r.width / 2, y: r.y + r.height - 6 }; })()`);
const dragEnd = { x: y.x, y: y.y };
await cdp.send('Input.dispatchMouseEvent', { type: 'mousePressed', x: dragStart.x, y: dragStart.y, button: 'left', clickCount: 1, buttons: 1 });
await sleep(60);
for (let step = 1; step <= 6; step += 1) {
  const x = dragStart.x + ((dragEnd.x - dragStart.x) * step) / 6;
  await cdp.send('Input.dispatchMouseEvent', { type: 'mouseMoved', x, y: dragEnd.y, button: 'left', buttons: 1 });
  await sleep(25);
}
const midHint = await cdp.eval(`document.querySelector('#year-histogram-hint')?.textContent || ''`);
const midBrush = await cdp.eval(`document.querySelectorAll('#year-histogram .is-brushing').length`);
await cdp.send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: dragEnd.x, y: dragEnd.y, button: 'left', buttons: 0 });
await sleep(500);
const afterDrag = await cdp.eval(`(() => ({
  search: location.search,
  current: [...document.querySelectorAll('#year-histogram button')].filter((b) => b.getAttribute('aria-current') === 'true').map((b) => Number(b.dataset.start)),
  brushing: document.querySelectorAll('#year-histogram .is-brushing').length,
  hint: document.querySelector('#year-histogram-hint')?.textContent || '',
  rows: document.querySelectorAll('#result-list > *').length,
  count: document.querySelector('#result-count')?.textContent || '',
  from: document.querySelector('#year-from')?.value, to: document.querySelector('#year-to')?.value,
}))()`);
log(`DRAG ${from.start}->${to.start}: midHint="${midHint}" midBrushing=${midBrush}`);
log(`DRAG result: ${JSON.stringify(afterDrag)}`);
log(`EXPECT from=${from.start} to=${to.start + 9} <= clamp; ok=${Number(new URLSearchParams(afterDrag.search).get('from')) === from.start}`);

// --- single click on another bin ---
